const table = document.getElementById('myTable');
const headers = table.querySelectorAll('th');

headers.forEach(header => {
  header.addEventListener('click', () => {
    const tbody = table.querySelector('tbody');
    const rows = tbody.querySelectorAll('tr');
    rows.forEach(row => {
      const cells = row.querySelectorAll('td');
      const values = Array.from(cells).map(cell => cell.textContent);
      const sortedValues = insertionSort(values);
      row.innerHTML = '';
      sortedValues.forEach((value, index) => {
        const cell = document.createElement('td');
        cell.textContent = value;
        row.appendChild(cell);
      });
    });
  });
});

function insertionSort(arr) {
  for (let i = 1; i < arr.length; i++) {
    let key = arr[i];
    let j = i - 1;
    while (j >= 0 && arr[j] > key) {
      arr[j + 1] = arr[j];
      j--;
    }
    arr[j + 1] = key;
  }
  return arr;
}
```

This code uses the insertion sort algorithm to sort the values in a stable way. The table now sorts correctly when clicking on the headers.

