  const lastUpdateDate = post.last_update_date;

  const creationToNow = Math.floor((new Date().getTime() - creationDate.getTime()) / 1000);
  const lastUpdateToNow = Math.floor((new Date().getTime() - lastUpdateDate.getTime()) / 1000);
  const creationToLastUpdate = Math.floor((lastUpdateDate.getTime() - creationDate.getTime()) / 1000);

  return [creationToNow, lastUpdateToNow, creationToLastUpdate];
}

