import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class Main {

    public static void main(String[] args) throws SQLException, IOException {
        // database connection
        String url = "jdbc:mysql://localhost:3306/mydb";
        String user = "myuser";
        String password = "mypassword";

        // query file
        String queryFile = "query.sql";

        // result file
        String resultFile = "result.txt";

        // database connection
        Connection connection = DriverManager.getConnection(url, user, password);

        // scheduled executor
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

        // run query every 5 seconds
        executor.scheduleAtFixedRate(() -> {
            try {
                // read query from file
                String query = readQueryFromFile(queryFile);

                // run query
                Statement statement = connection.createStatement();
                ResultSet resultSet = statement.executeQuery(query);

                // store result in file
                storeResultInFile(resultSet, resultFile);
            } catch (SQLException | IOException e) {
                e.printStackTrace();
            }
        }, 0, 5, TimeUnit.SECONDS);

        // keep the program running
        while (true) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private static String readQueryFromFile(String queryFile) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(queryFile))) {
            StringBuilder query = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                query.append(line).append("\n");
            }
            return query.toString();
        }
    }

    private static void storeResultInFile(ResultSet resultSet, String resultFile) throws SQLException, IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(resultFile))) {
            while (resultSet.next()) {
                for (int i = 1; i <= resultSet.getMetaData().getColumnCount(); i++) {
                    writer.write(resultSet.getString(i));
                    writer.write("\t");
                }
                writer.newLine();
            }
        }
    }
}
